const concepts = {
  A:{letter:'A',short:'DUAL WIND',title:'双屏物理解谜',desc:'上屏读懂风场，下屏完成击球。信息和动作各自有一个落点。',score:'9.2',surface:'UPPER + LOWER',reward:'PRECISION STAR',mode:'REGULAR / OPEN',hint:'拖动风场节点，再拉杆击球',fit:'最符合“折叠 = 新规则”的方向，把预判和执行拆成两个屏幕动作，教学感清晰。',loop:['读风场','拉杆','修正','入洞'],guards:['风力是关卡参数，不能由铰链角度决定。','上屏只做预判，下屏保留单指拖拽。','单屏入口改为“风场预览”按钮。'],tags:['风场预判','上下分屏','教学友好'],render:'dual'},
  B:{letter:'B',short:'HANDHELD',title:'半折掌机弹珠',desc:'上屏只看球道，下屏成为带有弹力回馈的单手操控区。',score:'8.6',surface:'UPPER / CONTROL DECK',reward:'COMBO SPARK',mode:'HALF-FOLD / TABLE',hint:'转动拉力环，让折痕成为反弹板',fit:'最有“掌机感”的方案。折痕不是装饰，而是一面可以读懂的反弹板。',loop:['蓄力','撞缝','反弹','连击'],guards:['中缝只做视觉与碰撞障碍，按钮必须避开。','反弹角度由球道几何决定，不由姿态决定。','手动掌机模式覆盖普通 iPhone。'],tags:['掌机触感','折痕反弹','组合技'],render:'handheld'},
  C:{letter:'C',short:'CANAL SHIFT',title:'中缝运河视差',desc:'把 division 画成可读的运河，让桥梁和加速线成为唯一跨越方式。',score:'9.0',surface:'REGULAR / LANDSCAPE',reward:'CANAL BOOST',mode:'REGULAR / SEAM',hint:'点击桥梁，寻找一次跨缝路线',fit:'最适合强化 FoldPutt 的品牌记忆点：中缝就是球场里的河。',loop:['看视差','搭桥','加速','跨缝'],guards:['运河视觉不遮挡可点控件。','桥梁是关卡道具，不增加第二套操作。','没有中缝时提供手动桥梁入口。'],tags:['中缝运河','桥梁道具','视差'],render:'canal'},
  D:{letter:'D',short:'QUICK → PLAN',title:'外屏快推 / 内屏策略',desc:'外屏给你一次限时快推，展开后把刚才的球路变成可读的下一杆策略。',score:'8.1',surface:'COMPACT → REGULAR',reward:'ROUTE INSIGHT',mode:'DUAL FORM / CONTINUITY',hint:'切换外屏与内屏，调整下一杆策略',fit:'最像产品化功能，能把“快玩”和“深玩”接成一条连续流程。',loop:['快推','展开','复盘','调整'],guards:['展开不能自动结算或重置一局。','策略编辑只改下一杆方向与路线提示。','没有 DUO 时用“球路复盘”手动入口。'],tags:['快节奏','球路复盘','连续性'],render:'strategy'},
  E:{letter:'E',short:'MIRROR TIME',title:'镜像时空高尔夫',desc:'现实球道与镜像球道同步滚动，一杆要同时满足两个世界的安全路线。',score:'8.8',surface:'REGULAR / SPLIT VIEW',reward:'PARALLEL STAR',mode:'REGULAR / MIRROR',hint:'拖动镜像障碍，找出两侧都安全的线路',fit:'最有惊喜感，也最需要清晰教学。镜像球只做同步规则，不引入额外参数。',loop:['观察','同步','避障','双入洞'],guards:['镜像球路使用同一手势映射。','颜色之外用线型和标签区分两侧。','单屏降级为前后叠层预览。'],tags:['双球同步','镜像障碍','高记忆点'],render:'mirror'}
};
let active = 'A';
let elapsed = 0;
let ticker;
const $ = id => document.getElementById(id);
function iconArrow(){return '<span class="concept-arrow">↗</span>'}
function renderList(){
  $('conceptList').innerHTML = Object.entries(concepts).map(([key,c])=>`<button class="concept-item ${key===active?'active':''}" data-concept="${key}"><span class="concept-letter">${c.letter}</span><span class="concept-label"><strong>${c.title}</strong><span>${c.short}</span></span>${iconArrow()}</button>`).join('');
  document.querySelectorAll('.concept-item').forEach(btn=>btn.addEventListener('click',()=>selectConcept(btn.dataset.concept)));
}
function selectConcept(key){active=key;renderList();const c=concepts[key];$('conceptKicker').textContent=`${c.letter} / ${c.short}`;$('conceptTitle').textContent=c.title;$('conceptDesc').textContent=c.desc;$('fitScore').textContent=c.score;$('fitSummary').textContent=c.fit;$('activeSurface').textContent=c.surface;$('rewardLoop').textContent=c.reward;$('stageMode').textContent=c.mode;$('stageHint').textContent=c.hint;$('playLoop').innerHTML=c.loop.map((x,i)=>`${i?'<span class="loop-arrow">›</span>':''}<span class="loop-step">${x}</span>`).join('');$('guardrails').innerHTML=c.guards.map(x=>`<li>${x}</li>`).join('');$('signalTags').innerHTML=c.tags.map(x=>`<span class="tag">${x}</span>`).join('');renderDevice(c.render);log(`已切换到 ${c.letter} · ${c.title}`);}
function renderDevice(kind){
  const root=$('deviceWrap');
  const art=(label,extra='')=>`<div class="screen ${extra}"><div class="course-art"></div><div class="glass-overlay"></div><span class="screen-label">${label}</span></div>`;
  if(kind==='dual') root.innerHTML=`<div class="device" data-kind="dual">${art('MACRO / WIND MAP','screen-upper')}<div class="screen screen-lower"><div class="course-art"></div><div class="screen-grid"></div><div class="glass-overlay"></div><span class="screen-label">MICRO / PUTT DECK</span><div class="trajectory"></div><div class="micro-ball"></div><button class="launch-btn" id="launch">PUTT ↗</button></div><div class="wind-vectors"><i></i><i></i><i></i><i></i></div><button class="wind-node" id="windNode" aria-label="拖动风场节点"></button><div class="control-pad"><div class="power-ring" id="powerRing"></div><span class="pad-label">PULL / RELEASE</span><strong class="pad-value" id="powerValue">68<small>%</small></strong></div><div class="hinge-orb"></div></div>`;
  if(kind==='handheld') root.innerHTML=`<div class="device" data-kind="handheld" style="transform:rotateX(5deg) rotateY(-8deg)">${art('COURSE / TOP SCREEN','screen-upper')}<div class="screen screen-lower"><div class="course-art"></div><div class="glass-overlay"></div><span class="screen-label">CONTROL DECK / HALF-FOLD</span><div class="control-pad"><div class="power-ring" id="powerRing"></div><span class="pad-label">REBOUND POWER</span><strong class="pad-value" id="powerValue">42<small>%</small></strong></div></div><div class="fold-seam"></div><div class="hinge-orb"></div></div>`;
  if(kind==='canal') root.innerHTML=`<div class="device" data-kind="canal" style="transform:rotateX(3deg) rotateY(-3deg)">${art('LEFT BANK','screen-side left')}<div class="screen screen-side right"><div class="course-art"></div><div class="glass-overlay"></div><span class="screen-label">RIGHT BANK</span></div><div class="canal-lines"></div><button class="bridge" id="bridge" aria-label="放置桥梁"></button><div class="micro-ball"></div><div class="hinge-orb"></div></div>`;
  if(kind==='strategy') root.innerHTML=`<div class="device" data-kind="strategy" style="transform:rotateX(4deg)">${art('COMPACT / QUICK PUSH','screen-upper')}<div class="screen screen-lower"><div class="course-art"></div><div class="glass-overlay"></div><span class="screen-label">REGULAR / ROUTE EDITOR</span><div class="strategy-toolbar"><span class="toolbar-label">NEXT SHOT / ROUTE PREVIEW</span><button class="active">ARC</button><button>SAFE</button><button>BOOST</button><button id="quickLaunch">SHOT ↗</button></div></div><div class="hinge-orb"></div></div>`;
  if(kind==='mirror') root.innerHTML=`<div class="device" data-kind="mirror" style="transform:rotateX(4deg)">${art('REALITY','screen-side left')}<div class="screen screen-side right"><div class="course-art mirror"></div><div class="glass-overlay"></div><span class="screen-label">MIRROR / OFFSET</span><div class="mirror-ball"></div></div><div class="sync-line"></div><div class="micro-ball"></div><div class="hinge-orb"></div></div>`;
  wireDevice(kind);
}
function wireDevice(kind){
  const ring=$('powerRing'); if(ring){ring.addEventListener('pointermove',e=>{if(e.buttons){const v=Math.max(12,Math.min(98,Math.round((e.clientX-ring.getBoundingClientRect().left)/ring.offsetWidth*130)));$('powerValue').innerHTML=`${v}<small>%</small>`;log(`拉力环：${v}%，松手即击球`);}});ring.addEventListener('click',()=>{ring.classList.add('hit');setTimeout(()=>ring.classList.remove('hit'),700);log(kind==='handheld'?'弹珠撞上折痕，反弹角度已锁定。':'已锁定这一杆的力度。');});}
  const launch=$('launch');if(launch)launch.addEventListener('click',()=>shot('micro-ball','击球！预测线变成真实球路。'));
  const node=$('windNode');if(node){node.addEventListener('pointerdown',e=>{node.setPointerCapture(e.pointerId);node.dataset.drag='1'});node.addEventListener('pointermove',e=>{if(node.dataset.drag){const r=node.parentElement.getBoundingClientRect();node.style.left=`${Math.max(10,Math.min(85,(e.clientX-r.left)/r.width*100))}%`;node.style.top=`${Math.max(15,Math.min(80,(e.clientY-r.top)/r.height*100))}%`;log('风场节点已移动，微缩球道同步更新。')}});node.addEventListener('pointerup',()=>{node.dataset.drag='';});}
  const bridge=$('bridge');if(bridge)bridge.addEventListener('click',()=>{bridge.style.width='25%';bridge.style.left='37.5%';bridge.style.background='linear-gradient(90deg,var(--mint-2),var(--gold),var(--mint-2))';log('桥梁已展开，中缝进入可通行状态。')});
  const quick=$('quickLaunch');if(quick)quick.addEventListener('click',()=>{shot('micro-ball','外屏快推完成，内屏已生成下一杆策略。');$('stageMode').textContent='CONTINUITY / ROUTE SAVED'});
}
function shot(selector,message){const ball=document.querySelector(`.${selector}`);if(ball){ball.classList.add('hit');ball.style.transform='translate(190px,-52px) scale(.75)';setTimeout(()=>{ball.style.transform='';ball.classList.remove('hit')},900)}log(message);}
function log(message){$('interactionLog').textContent=message;elapsed=0;clearInterval(ticker);ticker=setInterval(()=>{elapsed++;$('logTime').textContent=`00:${String(elapsed).padStart(2,'0')}`},1000)}
function reset(){selectConcept(active);log('舞台已重置，等待你的第一次击球……')}
renderList();selectConcept('A');$('resetStage').addEventListener('click',reset);$('reduceMotion').addEventListener('click',()=>{document.body.classList.toggle('reduce-motion');log(document.body.classList.contains('reduce-motion')?'已开启减少动效。':'已恢复动效。')});
